--[[\n    EventService.lua\n    Handles all custom game events and signal broadcasting\n    Used throughout the game for triggering mechanics\n]]\n\nlocal EventService = {}\nlocal Signal = {}\nSignal.__index = Signal\n\n-- Create a new signal\nfunction Signal.new()\n    local self = setmetatable({}, Signal)\n    self._bindable = Instance.new("BindableEvent")\n    return self\nend\n\n-- Fire the signal with arguments\nfunction Signal:Fire(...)\n    self._bindable:Fire(...)\nend\n\n-- Connect a function to the signal\nfunction Signal:Connect(callback)\n    return self._bindable.Event:Connect(callback)\nend\n\n-- Wait for signal to fire\nfunction Signal:Wait()\n    return self._bindable.Event:Wait()\nend\n\n-- Cleanup\nfunction Signal:Destroy()\n    self._bindable:Destroy()\nend\n\n-- EventService implementation\nEventService._events = {}\n\n-- Create or get an event\nfunction EventService:CreateEvent(eventName)\n    if not self._events[eventName] then\n        self._events[eventName] = Signal.new()\n    end\n    return self._events[eventName]\nend\n\n-- Fire an event\nfunction EventService:FireEvent(eventName, ...)\n    local event = self:CreateEvent(eventName)\n    event:Fire(...)\nend\n\n-- Connect to an event\nfunction EventService:Connect(eventName, callback)\n    local event = self:CreateEvent(eventName)\n    return event:Connect(callback)\nend\n\n-- Wait for an event\nfunction EventService:Wait(eventName)\n    local event = self:CreateEvent(eventName)\n    return event:Wait()\nend\n\nreturn EventService